package com.lexorion.platform.audit;
import com.lexorion.core.audit.AuditRecorder;
import com.lexorion.platform.security.AuthenticatedUser;import com.lexorion.horizon.tenantaccess.context.TenantAccessContextHolder;import jakarta.servlet.http.*;import org.springframework.stereotype.Component;import org.springframework.web.servlet.HandlerInterceptor;
@Component public class AdministrativeAuditInterceptor implements HandlerInterceptor{private final AuditRecorder audit;private final TenantAccessContextHolder tenants;public AdministrativeAuditInterceptor(AuditRecorder audit,TenantAccessContextHolder tenants){this.audit=audit;this.tenants=tenants;}@Override public void afterCompletion(HttpServletRequest request,HttpServletResponse response,Object handler,Exception error){if(!isMutation(request)||!isAudited(request.getRequestURI()))return;var auth=org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();var principal=auth!=null&&auth.getPrincipal() instanceof AuthenticatedUser user?user:null;var tenant=tenants.get().orElse(null);audit.record(principal==null?null:principal.userId(),tenant==null?null:tenant.organizationId(),null,request.getMethod()+" "+request.getRequestURI(),"HTTP_MUTATION",request.getRequestURI(),error==null&&response.getStatus()<400?"SUCCESS":"FAILURE");}private boolean isMutation(HttpServletRequest request){return !java.util.Set.of("GET","HEAD","OPTIONS").contains(request.getMethod());}private boolean isAudited(String path){return path.startsWith("/api/tenant/")||path.startsWith("/api/platform/organizations")||path.startsWith("/api/platform/products")||path.startsWith("/api/platform/plans")||path.startsWith("/api/platform/entitlements");}}
